<h1>Categories</h1><form method="get"><input type="hidden" name="action" value="categories"><input name="q" placeholder="Search"><button>Search</button></form><form method="post" action="<?= e(url('admin/?action=save_category')) ?>"><?= csrf_field() ?><input name="name" required placeholder="Name"><input name="slug" placeholder="Slug"><textarea name="description" placeholder="Description"></textarea><button>Add</button></form><?php foreach($cats as $c): ?><div class="card"><form method="post" action="<?= e(url('admin/?action=save_category&id='.$c['id'])) ?>"><?= csrf_field() ?><input name="name" value="<?= e($c['name']) ?>"><input name="slug" value="<?= e($c['slug']) ?>"><textarea name="description"><?= e($c['description']) ?></textarea><button>Save</button></form><form method="post" action="<?= e(url('admin/?action=delete_category&id='.$c['id'])) ?>"><?= csrf_field() ?><button class="danger">Delete</button></form></div><?php endforeach; ?>
